search='''<section class="intermediate2-search course-search-panel" data-course-search-panel data-search-target="#unit6-content" data-search-items=".ie2-search-item" aria-label="Search Unit 6"><label class="course-search-label" for="u6-search">Find a topic or expression</label><div class="course-search-row"><input id="u6-search" type="search" data-course-search-input placeholder="Try: told, drought, tomorrow, carry out…" autocomplete="off"/><button type="button" class="course-search-clear" data-course-search-clear hidden>Clear</button></div><p class="course-search-meta"><span data-course-search-count></span><span>Choose a topic to open its explanation.</span></p></section><p class="course-search-empty" data-course-search-empty hidden>No matching topic. Try another word.</p></div>'''
